// full encrypt: returns ciphertext (len pt) and 16-byte tag
void chacha20poly1305_encrypt(const uint8_t* key, const uint8_t* nonce,
                              const uint8_t* pt, size_t ptlen,
                              const uint8_t* aad, size_t aadlen,
                              uint8_t* ct, uint8_t* tag){
  u32 k[8];
  for(int i=0;i<8;i++) k[i] = (u32)key[4*i] | ((u32)key[4*i+1]<<8) | ((u32)key[4*i+2]<<16) | ((u32)key[4*i+3]<<24);
  u32 n[3];
  for(int i=0;i<3;i++) n[i] = (u32)nonce[4*i] | ((u32)nonce[4*i+1]<<8) | ((u32)nonce[4*i+2]<<16) | ((u32)nonce[4*i+3]<<24);

  // generate poly key = first block (counter 0)
  u32 block0[16];
  chacha20_block(k, 0, n, block0);
  uint8_t polykey[32];
  for(int i=0;i<8;i++){
    polykey[4*i] = (uint8_t)(block0[i] & 0xff);
    polykey[4*i+1] = (uint8_t)((block0[i]>>8)&0xff);
    polykey[4*i+2] = (uint8_t)((block0[i]>>16)&0xff);
    polykey[4*i+3] = (uint8_t)((block0[i]>>24)&0xff);
  }

  u32 r[4], s[4];
  poly1305_init(r, s, polykey);

  // encrypt plaintext with counter starting at 1
  u32 counter = 1;
  size_t off = 0;
  u32 blk[16];
  uint8_t keystream[64];
  while(off + 64 <= ptlen){
    chacha20_block(k, counter, n, blk);
    for(int i=0;i<16;i++){
      u32 v = blk[i];
      uint8_t* o = ct + off + 4*i;
      o[0] = (uint8_t)(v & 0xff) ^ pt[off+4*i];
      o[1] = (uint8_t)((v>>8)&0xff) ^ pt[off+4*i+1];
      o[2] = (uint8_t)((v>>16)&0xff) ^ pt[off+4*i+2];
      o[3] = (uint8_t)((v>>24)&0xff) ^ pt[off+4*i+3];
    }
    off += 64; counter++;
  }
  if(off < ptlen){
    chacha20_block(k, counter, n, blk);
    for(int i=0;i<16;i++){
      keystream[4*i] = (uint8_t)(blk[i]&0xff);
      keystream[4*i+1] = (uint8_t)((blk[i]>>8)&0xff);
      keystream[4*i+2] = (uint8_t)((blk[i]>>16)&0xff);
      keystream[4*i+3] = (uint8_t)((blk[i]>>24)&0xff);
    }
    for(size_t i=off;i<ptlen;i++) ct[i] = keystream[i-off] ^ pt[i];
  }

  // poly1305 over aad || ct || lengths
  u32 h[5] = {0,0,0,0,0};
  poly1305_blocks(h, r, aad, aadlen);
  if(aadlen % 16){
    uint8_t pad[16] = {0};
    poly1305_blocks(h, r, pad, 16 - (aadlen%16));
  }
  poly1305_blocks(h, r, ct, ptlen);
  if(ptlen % 16){
    uint8_t pad[16] = {0};
    poly1305_blocks(h, r, pad, 16 - (ptlen%16));
  }
  // lengths
  uint8_t lens[16];
  u64 al = (u64)aadlen, pl = (u64)ptlen;
  for(int i=0;i<8;i++) lens[i] = (uint8_t)(al>>(8*i));
  for(int i=0;i<8;i++) lens[8+i] = (uint8_t)(pl>>(8*i));
  poly1305_blocks(h, r, lens, 16);
  poly1305_finish(h, s, tag);
}
