static size_t N;
static uint8_t *a, *b;
static int nthreads;

void* copy_worker(void* arg){
  long id = (long)arg;
  size_t chunk = N / nthreads;
  size_t start = id*chunk;
  size_t end = (id==nthreads-1)? N : start+chunk;
  memcpy(b+start, a+start, end-start);
  return NULL;
}

int main(){
