#include <time.h>
#include <stdint.h>

double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return ts.tv_sec + ts.tv_nsec/1e9; }

extern void ChaCha20_ctr32(unsigned char *out, const unsigned char *inp, size_t len, const unsigned int key[8], const unsigned int counter[4]);

int main(){
  size_t msglen = 40*1024*1024;
  uint8_t* key = malloc(32);
  uint8_t* nonce = malloc(12);
  uint8_t* pt = malloc(msglen);
  uint8_t* ct = malloc(msglen);
  for(int i=0;i<32;i++) key[i]=i;
  for(int i=0;i<12;i++) nonce[i]=i+100;
